WITH eligible AS (SELECT s.* FROM suppliers s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.product_name LIKE '%Office%')) SELECT CASE WHEN rating >= 4.5 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, SUM(CASE WHEN country = 'DE' THEN rating ELSE 0 END) AS de_rating, SUM(CASE WHEN city = 'Bangkok' THEN rating ELSE 0 END) AS bangkok_rating, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'Chiang Mai' THEN 1 END), 0), 2) AS rating_per_chiang_mai, GROUPING(CASE WHEN rating >= 4.5 THEN 'LARGE' ELSE 'SMALL' END) AS gid FROM eligible GROUP BY ROLLUP (CASE WHEN rating >= 4.5 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY rating_tier NULLS FIRST
